package dev.saffron;

import java.util.*;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.JsonNode;
import static org.springframework.http.HttpStatus.*;

@Service public class PaymentOperations {
 private final JdbcTemplate db;private final Tracking tracking;private final PaymentGateway gateway;private final NotificationInbox inbox;
 PaymentOperations(JdbcTemplate db,Tracking tracking,PaymentGateway gateway,NotificationInbox inbox){this.inbox=inbox;this.db=db;this.tracking=tracking;this.gateway=gateway;}
 static long money(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
 static UUID uuid(Map<String,Object> row,String key){return (UUID)row.get(key);}
 private Map<String,Object> lock(UUID id){var refs=db.queryForList("select order_id from payments where id=?",id);if(refs.isEmpty())throw new ResponseStatusException(NOT_FOUND);db.queryForMap("select * from orders where id=? for update",refs.getFirst().get("order_id"));return db.queryForMap("select * from payments where id=? for update",id);}
 private void emit(UUID order,String type){db.update("update orders set version=version+1 where id=?",order);tracking.record(order);inbox.order(order,type);db.update("insert into outbox(id,aggregate_id,event_type,payload) values(?,?,?,?)",UUID.randomUUID(),order,type,"{\"orderId\":\""+order+"\"}");}
 void issue(UUID payment,String code,String resource){db.update("insert into payment_issues(id,payment_id,code,resource) values(?,?,?,?) on conflict(payment_id,code,resource) do update set state='OPEN',seen_count=payment_issues.seen_count+1,last_seen=now()",UUID.randomUUID(),payment,code,resource.length()>200?resource.substring(0,200):resource);}
 @Transactional public boolean session(UUID payment,JsonNode object,String eventType){var p=lock(payment);return applySession(p,object,eventType);}
 static String reference(JsonNode node){return node.isString()?node.asString():node.path("id").asString("");}
 @Transactional public void register(UUID order,long amount){db.update("insert into payments(id,order_id,provider,amount) values(?,?,?,?)",UUID.randomUUID(),order,gateway.provider(),amount);}
 boolean exists(UUID order){return db.queryForObject("select count(*) from payments where order_id=?",Integer.class,order)>0;}
 void assertFulfillment(UUID order){var rows=db.queryForList("select id,captured_amount,amount from payments where order_id=?",order);if(rows.isEmpty())return;var p=rows.getFirst();if(money(p,"captured_amount")!=money(p,"amount")||db.queryForObject("select count(*) from payment_issues where payment_id=? and state='OPEN'",Integer.class,p.get("id"))>0)throw new ResponseStatusException(CONFLICT,"Confirmed payment and resolved payment issues required");}
 private boolean applySession(Map<String,Object> p,JsonNode object,String eventType){UUID id=uuid(p,"id"),order=uuid(p,"order_id");String session=object.path("id").asString("");
 if(object.path("livemode").asBoolean(true)||!session.startsWith("cs_test_")||!object.path("metadata").path("paymentId").asString("").equals(id.toString())||!object.path("client_reference_id").asString("").equals(order.toString())||!object.path("currency").asString("").equals(p.get("currency"))||!object.path("amount_total").isIntegralNumber()||object.path("amount_total").asLong()!=money(p,"amount")){
 issue(id,"AMOUNT_CURRENCY_REFERENCE_MISMATCH",session);if(money(p,"captured_amount")==0){db.update("update payments set state='REVIEW',last_error='Provider snapshot mismatch' where id=?",id);db.update("update orders set payment='REVIEW' where id=?",order);}return false;}
 if(p.get("session_id")!=null&&!p.get("session_id").equals(session)){issue(id,"SESSION_REFERENCE_MISMATCH",session);return false;}
 String url=object.path("url").asString("");if(!url.isBlank())url=gateway.safeCheckoutUrl(url);
 db.update("update payments set session_id=?,checkout_url=coalesce(?,checkout_url),lease_until='-infinity',next_reconcile=now()+interval '15 seconds',last_error=null where id=?",session,url.isBlank()?null:url,id);
 if("paid".equals(object.path("payment_status").asString())&&"complete".equals(object.path("status").asString())){
 String intent=reference(object.path("payment_intent"));if(!intent.startsWith("pi_")){issue(id,"MISSING_PAYMENT_REFERENCE",session);return false;}
 if(p.get("intent_id")!=null&&!p.get("intent_id").equals(intent)){issue(id,"PAYMENT_REFERENCE_MISMATCH",intent);return false;}
 if(money(p,"captured_amount")==0){
 db.update("update payments set captured_amount=amount,state='PAID',intent_id=? where id=?",intent,id);db.update("insert into ledger(order_id,kind,amount) values(?,'PAYMENT_CAPTURE',?) on conflict do nothing",order,money(p,"amount"));
 var o=db.queryForMap("select state from orders where id=?",order);boolean cancelled=o.get("state").equals("CANCELLED");
 db.update("update orders set payment='PAID',state=case when state='AWAITING_PAYMENT' then 'PLACED' else state end where id=?",order);
 if(cancelled)cancel(order);emit(order,"PaymentSucceeded");if(!cancelled)emit(order,"OrderPlaced");
 }return true;
 }
 if(money(p,"captured_amount")>0)return true; // Stale unpaid/expired events cannot reverse confirmed money.
 if("expired".equals(object.path("status").asString())){db.update("update payments set state='EXPIRED' where id=?",id);int changed=db.update("update orders set payment=case when state='CANCELLED' then 'UNPAID' else 'FAILED' end where id=? and payment is distinct from (case when state='CANCELLED' then 'UNPAID' else 'FAILED' end)",order);if(!p.get("state").equals("EXPIRED")||changed>0)emit(order,"PaymentExpired");}
 else if(eventType.equals("checkout.session.async_payment_failed")&&!p.get("state").equals("FAILED")){db.update("update payments set state='FAILED' where id=?",id);db.update("update orders set payment='FAILED' where id=?",order);emit(order,"PaymentFailed");}
 else if(!Set.of("FAILED","EXPIRED").contains(p.get("state"))){db.update("update payments set state='OPEN' where id=?",id);db.update("update orders set payment='PENDING' where id=? and payment in ('PENDING','UNKNOWN','REVIEW')",order);}
 return true;
 }
 @Transactional public void cancel(UUID order){var refs=db.queryForList("select id from payments where order_id=?",order);if(refs.isEmpty())return;var p=lock((UUID)refs.getFirst().get("id"));db.update("update payments set cancel_requested=true,next_reconcile=now() where id=?",p.get("id"));long reserved=reserved(uuid(p,"id")),remaining=money(p,"captured_amount")-reserved;if(remaining>0)requestRefund(p,"auto-cancel",remaining,"Order cancellation","system");else if(money(p,"captured_amount")==0)db.update("update orders set payment='CANCELLATION_PENDING' where id=?",order);}
 private long reserved(UUID payment){return db.queryForObject("select coalesce(sum(amount),0)::bigint from refunds where payment_id=? and state<>'FAILED'",Long.class,payment);}
 @Transactional public Map<String,Object> requestRefund(UUID order,String key,long amount,String reason,String actor){var refs=db.queryForList("select id from payments where order_id=?",order);if(refs.isEmpty())throw new ResponseStatusException(CONFLICT,"No sandbox payment for this order");var p=lock((UUID)refs.getFirst().get("id"));if(!p.get("provider").equals(gateway.provider()))throw new ResponseStatusException(CONFLICT,"Use the configured provider worker for this payment");String state=db.queryForObject("select state from orders where id=?",String.class,order);if(!Set.of("CANCELLED","DELIVERED").contains(state))throw new ResponseStatusException(CONFLICT,"Cancel the order or wait for delivery before issuing a refund");return requestRefund(p,key,amount,reason,actor);}
 private Map<String,Object> requestRefund(Map<String,Object> p,String key,long amount,String reason,String actor){
 if(key==null||!key.matches("[A-Za-z0-9-]{8,100}")||amount<1||reason==null||reason.isBlank()||reason.length()>200||reason.codePoints().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Positive refund amount, reason and idempotency key required");
 var old=db.queryForList("select * from refunds where payment_id=? and idempotency_key=?",p.get("id"),key);if(!old.isEmpty()){if(money(old.getFirst(),"amount")!=amount||!old.getFirst().get("reason").equals(reason))throw new ResponseStatusException(CONFLICT,"Refund key reused with different parameters");return old.getFirst();}
 if(amount>money(p,"captured_amount")-reserved(uuid(p,"id")))throw new ResponseStatusException(CONFLICT,"Refund exceeds captured amount remaining after pending refunds");
 UUID refund=UUID.randomUUID();db.update("insert into refunds(id,payment_id,order_id,amount,idempotency_key,reason,requested_by) values(?,?,?,?,?,?,?)",refund,p.get("id"),p.get("order_id"),amount,key,reason,actor);db.update("update orders set payment='REFUND_PENDING' where id=?",p.get("order_id"));db.update("insert into audit(actor,action,resource) values(?,'REFUND_REQUESTED',?)",actor,refund.toString());return db.queryForMap("select * from refunds where id=?",refund);
 }
 @Transactional public boolean refund(UUID payment,JsonNode object){var p=lock(payment);UUID order=uuid(p,"order_id");UUID id;try{id=UUID.fromString(object.path("metadata").path("refundId").asString());}catch(Exception e){issue(payment,"UNTRACKED_PROVIDER_REFUND",object.path("id").asString("unknown"));return false;}
 var rows=db.queryForList("select * from refunds where id=? and payment_id=? for update",id,payment);if(rows.isEmpty()){issue(payment,"UNTRACKED_PROVIDER_REFUND",object.path("id").asString("unknown"));return false;}var r=rows.getFirst();String provider=object.path("id").asString("");
 if(object.path("livemode").asBoolean(false)||!provider.startsWith("re_")||object.path("amount").asLong(-1)!=money(r,"amount")||!object.path("currency").asString("").equals(p.get("currency"))||!reference(object.path("payment_intent")).equals(p.get("intent_id"))||(r.get("provider_id")!=null&&!r.get("provider_id").equals(provider))){issue(payment,"REFUND_SNAPSHOT_MISMATCH",provider);return false;}
 if(r.get("state").equals("SUCCEEDED"))return true;
 String status=object.path("status").asString();String next=switch(status){case "succeeded"->"SUCCEEDED";case "failed","canceled"->"FAILED";default->"PENDING";};
 if(r.get("state").equals("FAILED")&&next.equals("PENDING"))return true;
 if(next.equals("SUCCEEDED")){
 long before=money(p,"refunded_amount"),after=Math.addExact(before,money(r,"amount"));if(after>money(p,"captured_amount")){issue(payment,"REFUND_EXCEEDS_CAPTURE",provider);return false;}
 db.update("insert into ledger(order_id,kind,amount) values(?,?,?) on conflict do nothing",order,"PAYMENT_REFUND:"+id,-money(r,"amount"));
 if("DELIVERED".equals(db.queryForObject("select state from orders where id=?",String.class,order)))reverseAllocations(order,id,before,after,money(p,"captured_amount"));
 db.update("update payments set refunded_amount=? where id=?",after,payment);
 }
 db.update("update refunds set state=?,provider_id=?,lease_until='-infinity',next_attempt=now()+interval '15 seconds',updated_at=now(),last_error=null where id=?",next,provider,id);
 refreshFinancial(order,payment);if(!r.get("state").equals(next))emit(order,next.equals("SUCCEEDED")?"RefundCompleted":"RefundUpdated");return true;
 }
 private void refreshFinancial(UUID order,UUID payment){var p=db.queryForMap("select * from payments where id=?",payment);long pending=db.queryForObject("select count(*) from refunds where payment_id=? and state not in ('SUCCEEDED','FAILED')",Long.class,payment);String state=pending>0?"REFUND_PENDING":money(p,"refunded_amount")==money(p,"captured_amount")?"REFUNDED":money(p,"refunded_amount")>0?"PARTIALLY_REFUNDED":"PAID";db.update("update orders set payment=? where id=?",state,order);}
 // Explicit demo allocation policy: reverse food first, then tax, then delivery. Monotone and exact in paise.
 static long[] allocation(long[] original,long refunded,long captured){if(captured<=0||refunded<0||refunded>captured||Arrays.stream(original).anyMatch(x->x<0)||Arrays.stream(original).sum()!=captured)throw new IllegalArgumentException("Invalid refund allocation");long[] result=new long[original.length];long remaining=refunded;for(int i=0;i<original.length;i++){result[i]=Math.min(original[i],remaining);remaining-=result[i];}return result;}
 private void reverseAllocations(UUID order,UUID refund,long before,long after,long captured){var o=db.queryForMap("select * from orders where id=?",order);long[] original={money(o,"item_subtotal")-money(o,"discount_amount"),money(o,"tax_amount"),money(o,"delivery_fee")};long[] old=allocation(original,before,captured),now=allocation(original,after,captured);String[] kinds={"FOOD_REFUND_REVERSAL:","TAX_REFUND_REVERSAL:","DELIVERY_REFUND_REVERSAL:"};for(int i=0;i<3;i++)if(now[i]!=old[i])db.update("insert into ledger(order_id,kind,amount) values(?,?,?) on conflict do nothing",order,kinds[i]+refund,old[i]-now[i]);}
 @Transactional public List<Map<String,Object>> claimPayments(){var rows=db.queryForList("select * from payments where provider=? and lease_until<now() and ((session_id is null and state in ('CREATING','UNKNOWN','REVIEW') and attempts<8 and next_attempt<=now() and created_at>now()-interval '20 hours') or (session_id is not null and next_reconcile<=now())) order by case when session_id is null then 0 else 1 end,next_reconcile,created_at limit 5 for update skip locked",gateway.provider());for(var p:rows)db.update("update payments set lease_until=now()+interval '60 seconds',attempts=attempts+case when session_id is null then 1 else 0 end where id=?",p.get("id"));return rows;}
 @Transactional public List<Map<String,Object>> claimRefunds(){var rows=db.queryForList("select r.*,p.intent_id from refunds r join payments p on p.id=r.payment_id where p.provider=? and r.lease_until<now() and r.state in ('REQUESTED','UNKNOWN','PENDING','REVIEW') and r.next_attempt<=now() and (r.provider_id is not null or (r.attempts<8 and r.created_at>now()-interval '20 hours')) order by r.next_attempt,r.created_at limit 5 for update of r skip locked",gateway.provider());for(var r:rows)db.update("update refunds set lease_until=now()+interval '60 seconds',attempts=attempts+1 where id=?",r.get("id"));return rows;}
 @Transactional public void paymentError(UUID id){var p=lock(id);if(money(p,"captured_amount")==0&&p.get("session_id")==null){db.update("update payments set state=case when attempts>=8 then 'REVIEW' else 'UNKNOWN' end,last_error='Provider request failed or timed out; outcome unresolved',lease_until='-infinity',next_attempt=now()+make_interval(secs=>least(60,power(2,least(6,attempts))::int)) where id=?",id);db.update("update orders set payment='UNKNOWN' where id=?",p.get("order_id"));}else db.update("update payments set lease_until='-infinity',last_error='Provider lookup unavailable',next_reconcile=now()+interval '15 seconds' where id=?",id);}
 @Transactional public void refundError(UUID id){var refs=db.queryForList("select payment_id from refunds where id=?",id);if(refs.isEmpty())return;lock((UUID)refs.getFirst().get("payment_id"));db.update("update refunds set state=case when provider_id is null and attempts>=8 then 'REVIEW' else 'UNKNOWN' end,lease_until='-infinity',last_error='Provider outcome unresolved',next_attempt=now()+make_interval(secs=>least(60,power(2,least(6,attempts))::int)) where id=? and state not in ('SUCCEEDED','FAILED')",id);}
 @Transactional public Map<String,Object> webhook(String provider,JsonNode event,String hash){String id=event.path("id").asString(""),type=event.path("type").asString("");if(id.isBlank()||id.length()>200||type.isBlank()||type.length()>100||event.path("livemode").asBoolean(true))throw new IllegalArgumentException("Valid test-mode event required");int inserted=db.update("insert into payment_webhook_inbox(provider,event_id,event_type,payload_hash,status) values(?,?,?,?,'ACCEPTED') on conflict do nothing",provider,id,type,hash);if(inserted==0){String original=db.queryForObject("select payload_hash from payment_webhook_inbox where provider=? and event_id=?",String.class,provider,id);if(!hash.equals(original))throw new ResponseStatusException(CONFLICT,"Event identifier reused with different content");return Map.of("duplicate",true);}
 var object=event.path("data").path("object");UUID payment;try{payment=UUID.fromString(object.path("metadata").path("paymentId").asString());}catch(Exception error){db.update("update payment_webhook_inbox set status='IGNORED' where provider=? and event_id=?",provider,id);return Map.of("ignored",true);}
 var existing=db.queryForList("select id from payments where id=? and provider=?",payment,provider);if(existing.isEmpty()){db.update("update payment_webhook_inbox set status='IGNORED' where provider=? and event_id=?",provider,id);return Map.of("ignored",true);}
 boolean applied;if(Set.of("checkout.session.completed","checkout.session.async_payment_succeeded","checkout.session.async_payment_failed","checkout.session.expired").contains(type))applied=session(payment,object,type);else if(Set.of("refund.created","refund.updated","refund.failed").contains(type))applied=refund(payment,object);else {db.update("update payment_webhook_inbox set status='IGNORED',payment_id=? where provider=? and event_id=?",payment,provider,id);return Map.of("ignored",true);}
 db.update("update payment_webhook_inbox set status=?,payment_id=? where provider=? and event_id=?",applied?"APPLIED":"QUARANTINED",payment,provider,id);return Map.of("accepted",true,"applied",applied);
 }
 @Transactional public void report(UUID id,JsonNode remote,JsonNode refunds){var p=lock(id);long captured="paid".equals(remote.path("payment_status").asString())?remote.path("amount_total").asLong():0,returned=0;boolean incomplete=refunds!=null&&refunds.path("has_more").asBoolean();if(refunds!=null)for(var r:refunds.path("data"))if("succeeded".equals(r.path("status").asString()))returned=Math.addExact(returned,r.path("amount").asLong());boolean mismatch=captured!=money(p,"captured_amount")||returned!=money(p,"refunded_amount")||incomplete;
 if(mismatch)issue(id,"PROVIDER_LOCAL_BALANCE_MISMATCH",p.get("session_id").toString());else db.update("update payment_issues set state='RESOLVED',last_seen=now() where payment_id=? and code in ('PROVIDER_LOCAL_BALANCE_MISMATCH','AMOUNT_CURRENCY_REFERENCE_MISMATCH')",id);
 db.update("insert into payment_reconciliations(payment_id,result,provider_state,local_capture,local_refunded) values(?,?,?,?,?)",id,mismatch?"MISMATCH":"MATCH",remote.path("payment_status").asString("unknown"),money(p,"captured_amount"),money(p,"refunded_amount"));db.update("update payments set last_reconciled=now(),next_reconcile=now()+interval '15 seconds',lease_until='-infinity' where id=?",id);
 }
 @Transactional public int reconcileNow(String actor){int count=db.update("update payments set next_reconcile=now(),next_attempt=now() where session_id is not null or (state in ('CREATING','UNKNOWN','REVIEW') and attempts<8)");db.update("insert into audit(actor,action,resource) values(?,'PAYMENTS_RECONCILE_REQUESTED',?)",actor,"payments="+count);return count;}
 @Transactional public void retry(UUID order,String user){var refs=db.queryForList("select p.id from payments p join orders o on o.id=p.order_id where o.id=? and o.customer_name=?",order,user);if(refs.isEmpty())throw new ResponseStatusException(NOT_FOUND);var p=lock((UUID)refs.getFirst().get("id"));if(money(p,"captured_amount")>0||p.get("state").equals("EXPIRED"))throw new ResponseStatusException(CONFLICT,"Payment already completed or session expired");if(money(p,"attempts")>=8)throw new ResponseStatusException(CONFLICT,"Operator review required; no new payment will be created");db.update("update payments set next_attempt=now(),next_reconcile=now() where id=?",p.get("id"));}
}
